using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Recovery;

internal sealed class CoherentUniformAmplificationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Uniform coherent rotation and an exact finite auxiliary-coin amplification circuit.",
        H("Whole-source coherent amplification"),
        Blocks(
            Paragraph(Text("Let S and L be arbitrary finite complex coordinate spaces, J an initialization isometry from S to L, C a supplied unitary on L, and P a self-adjoint idempotent good projection. Put U=CJ and suppose (PU)* PU=pI with 0<p<=1. For 0<p<1, Define W=PU/sqrt(p), B=(I-P)U/sqrt(1-p), theta=arcsin(sqrt(p)), and Q=(2UU*-I)(I-2P). The same Q acts on every source column; no unknown input state specifies a reflection.")),
            Describe.Lean(
                DescribeId.Create("uniform-operator-rotation"),
                DeclarationHandle.Create("D5/S3/Quantum/Recovery/CoherentUniformAmplification.uniform_operator_rotation"),
                H("Every power rotates the entire source"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Computability/brassardhoyermoscatapp2002amplification")),
                Blocks(
                    Paragraph(Text("At p=1, U=W already. For 0<p<1, the operators W and B satisfy W*W=B*B=I and W*B=0. For every natural n, Q^n U=sin((2n+1)theta)W+cos((2n+1)theta)B. This is an equality of rectangular operators on the whole source, derived from the scalar success Gram. Induction proves the identity for all powers after the two reflections are evaluated on the two isometric ranges.")),
                    Paragraph(Text("For any reference index type and any reference matrix R, tensoring the same identity with R preserves it. In particular, R=I preserves every joint source-reference vector and its density matrix, including entangled inputs. The statement uses no input-dependent choice of plane.")),
                    Paragraph(Text("This result is the uniform rotation mechanism of standard amplitude amplification. The finite auxiliary-coin construction below supplies the exact iteration choice and source-query bound. Coherent access to C and its inverse, both subspace reflections, and exact known coin rotations must be supplied; a destructive measurement interface does not supply them. Filter, reflection, and coin compilation costs are not included in a query count."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("exact-coherent-amplification"),
                DeclarationHandle.Create("D5/S3/Quantum/Recovery/CoherentUniformAmplification.exact_coherent_amplification"),
                H("A finite word with exact success on every source input"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Computability/brassardhoyermoscatapp2002amplification")),
                Blocks(
                    Paragraph(Text("Use the enlarged native ambient L direct-sum L and initialize the coin in its first label: K is the vertical block (J,0). The original operation lifts as diag(C,C). For q in [0,1], the known coin has blocks sqrt(q)I, -sqrt(1-q)I, sqrt(1-q)I, sqrt(q)I. Its adjoint is its inverse. The new good projection is diag(P,0), which requires both the old flag and the first coin label. All failed records remain coherent.")),
                    Paragraph(Text("For 0<p<1, choose n=ceil(pi/(4 arcsin(sqrt(p)))-1/2), a=pi/(4n+2), r=sin(a)^2 and q=r/p. The proof establishes 0<r<=p<1, 0<q<=1 and (2n+1)arcsin(sqrt(r))=pi/2. The enlarged prepared success Gram is rI. Its normalized successful isometry is exactly the original W with the fixed first coin label.")),
                    Paragraph(Text("Words are written in matrix-product order: the rightmost gate acts first. Each six-gate block is coin, C, initialization reflection, C-adjoint, coin-adjoint, good reflection. The initialization reflection is 2KK*-I and the good reflection is I-2 diag(P,0). Repeat that block n times, followed on the right by coin,C. Evaluation uses only J,C,P,q; W is absent from every gate. Direct reuse of the uniform rotation theorem shows that the evaluated word applied to K is (W,0), with (I-diag(P,0)) times this operator exactly zero. The evaluated operator is unitary on the entire enlarged ambient space. Tensoring with every reference matrix preserves the source equality.")),
                    Paragraph(Text("The word contains exactly 2n+1 original C or C-adjoint calls and satisfies 2n+1 <= (pi/2+2)/sqrt(p). When p=1, the word is just the lifted original C and uses one source call. This is the standard known-probability BHMT attenuation method; no algorithmic novelty is claimed. Exact real-angle coin rotations, coherent reversible source access and the two fixed subspace reflections are resources. No destructive measurement, reset, retry, unknown-input reflection or finite discrete-gate compilation is assumed. Filter, reflection and coin compilation costs are outside this source-query bound. The Petz-specific inverse-gate and filter construction additionally requires its own identification of the successful Kraus operators.")),
                    Paragraph(Text("To read the resulting native channel, fix the supplied output and environment coordinates L=O tensor E, or use the declared decoding into those coordinates. Keep the same J,C,P,p and the same finite word above. Set A=PCJ, W=A/sqrt(p), and K[a](i,j)=W((i,a),j) for each environment label a. The target channel is T(X)=sum_a K[a] X K[a]*. These Kraus operators come from the successful operator of this circuit; a flag probability alone does not specify them.")),
                    Paragraph(Text("The evaluated initialized word V is exactly (W,0) in the two coin labels. For any finite reference Z and any joint matrix X on S tensor Z, put Y=(V tensor I[Z]) X (V tensor I[Z])*. Discarding the coin and E means that the ((i,z),(j,t)) output entry is sum_a [Y((inl(i,a),z),(inl(j,a),t))+Y((inr(i,a),z),(inr(j,a),t))]. Substitution of V=(W,0) makes the second summand zero and gives exactly sum_a (K[a] tensor I[Z]) X (K[a] tensor I[Z])*. Thus the actual discarded output is (T tensor id[Z])(X), including every entangled density matrix. No product-state assumption or conclusion inferred only from a trace is used.")),
                    Paragraph(Text("The same operator equality and the unitarity of the finite word give W*W=I. Taking its environment slices gives sum_a K[a]* K[a]=I. The existing finite_kraus_quantum_channel construction therefore supplies a completely positive trace-preserving channel with exactly this Kraus action. Equivalently, expanding the two matrix products and regrouping the finite sums identifies Tr[E](W X W*) with T(X). This is an application of the whole-source identity and the finite Kraus channel construction.")),
                    Paragraph(Text("Before amplification the successful branch has slices A[a]=sqrt(p) K[a], so its joint-reference action is p times (T tensor id[Z]). On a normalized input its trace is p; conditioning on this observed success gives T tensor id[Z]. After amplification the finite word realizes that same map deterministically: the good projection fixes V and the complementary projection annihilates V. Both descriptions retain the same successful isometry and its native environment. At p=1 the original lifted circuit already supplies it. Discarding registers adds no C or C-adjoint calls, so the stated source-query bound and its exact-resource qualifications are preserved."))),
                DescribeRole.Theorem))));
}
